import networkx as nx
import random
import itertools

def check_girth(G, min_girth=6):
    """Check if graph has girth at least min_girth"""
    # Check for cycles of length 3, 4, 5
    for cycle_len in range(3, min_girth):
        # Check all possible cycles of this length
        for cycle in nx.simple_cycles(nx.DiGraph(G)):
            if len(cycle) == cycle_len:
                return False
    return True

def check_girth_better(G, min_girth=6):
    """More efficient girth check using BFS from each vertex"""
    n = G.number_of_nodes()
    for start in range(n):
        # BFS to find shortest cycle through start
        visited = {start: 0}
        queue = [(start, -1, 0)]  # (current, parent, depth)
        while queue:
            node, parent, depth = queue.pop(0)
            if depth >= min_girth - 1:
                continue
            for neighbor in G.neighbors(node):
                if neighbor == parent:
                    continue
                if neighbor in visited:
                    cycle_len = depth + 1 + visited[neighbor]
                    if cycle_len < min_girth:
                        return False
                else:
                    visited[neighbor] = depth + 1
                    queue.append((neighbor, node, depth + 1))
    return True

def is_k_colorable(G, k):
    """Check if graph is k-colorable using backtracking"""
    n = G.number_of_nodes()
    colors = [-1] * n

    def backtrack(v):
        if v == n:
            return True
        for c in range(k):
            valid = True
            for neighbor in G.neighbors(v):
                if colors[neighbor] == c:
                    valid = False
                    break
            if valid:
                colors[v] = c
                if backtrack(v + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

