part_b = list(range(8, 17))

solver = Optimize()

# Edge variables (only between parts)
x = {}
for i in part_a:
    for j in part_b:
        x[(i,j)] = Bool(f"e_{i}_{j}")

# Color variables
color = [Int(f"c_{i}") for i in range(n)]
for i in range(n):
    solver.add(color[i] >= 0, color[i] <= 3)

# If edge (i,j) exists, colors must differ
for i in part_a:
    for j in part_b:
        solver.add(Implies(x[(i,j)], color[i] != color[j]))

# At least 28 edges
edge_vars = [x[(i,j)] for i in part_a for j in part_b]
solver.add(Sum([If(e, 1, 0) for e in edge_vars]) >= target_edges)

# No 4-cycles: any two vertices in A share at most 1 neighbor in B
for i1 in part_a:
    for i2 in part_a:
        if i1 < i2:
            for j1 in part_b:
                for j2 in part_b:
                    if j1 < j2:
                        # Can't have edges (i1,j1), (i1,j2), (i2,j1), (i2,j2)
                        solver.add(Not(And(x[(i1,j1)], x[(i1,j2)], x[(i2,j1)], x[(i2,j2)])))

